CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, preferences jsonb NOT NULL DEFAULT '{}'::jsonb);
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_reviewcard_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES(NEW.id, coalesce(NEW.raw_user_meta_data->>'display_name', NEW.raw_user_meta_data->>'name', '')); RETURN NEW; END; $$;
CREATE TRIGGER reviewcard_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_reviewcard_profile();
CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, slug text NOT NULL UNIQUE, name text NOT NULL, category text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','paused','archived')), data jsonb NOT NULL DEFAULT '{}'::jsonb, ever_published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(slug ~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'), CHECK(slug NOT IN ('admin','api','login','new','dashboard','r','app','auth','settings')));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.businesses TO authenticated;
GRANT SELECT ON public.businesses TO anon;
GRANT ALL ON public.businesses TO service_role;
ALTER TABLE public.businesses ENABLE ROW LEVEL SECURITY;
CREATE POLICY business_public_read ON public.businesses FOR SELECT TO anon,authenticated USING(status='published');
CREATE POLICY business_owner_read ON public.businesses FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY business_owner_insert ON public.businesses FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid());
CREATE POLICY business_owner_update ON public.businesses FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE POLICY business_owner_delete_draft ON public.businesses FOR DELETE TO authenticated USING(owner_id=auth.uid() AND NOT ever_published);
CREATE FUNCTION public.protect_reviewcard_slug() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.slug<>OLD.slug THEN RAISE EXCEPTION 'Business URLs are permanent'; END IF; IF TG_OP='UPDATE' AND OLD.ever_published THEN NEW.ever_published=true; END IF; IF NEW.status='published' THEN NEW.ever_published=true; END IF; NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER business_slug_guard BEFORE INSERT OR UPDATE ON public.businesses FOR EACH ROW EXECUTE FUNCTION public.protect_reviewcard_slug();
CREATE TABLE public.card_designs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES public.businesses(id), owner_id uuid NOT NULL, name text NOT NULL DEFAULT 'Untitled card', design jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.card_designs TO authenticated;
GRANT ALL ON public.card_designs TO service_role;
ALTER TABLE public.card_designs ENABLE ROW LEVEL SECURITY;
CREATE POLICY designs_owner_read ON public.card_designs FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY designs_owner_insert ON public.card_designs FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=business_id AND b.owner_id=auth.uid()));
CREATE POLICY designs_owner_update ON public.card_designs FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid() AND EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=business_id AND b.owner_id=auth.uid()));
CREATE POLICY designs_owner_delete ON public.card_designs FOR DELETE TO authenticated USING(owner_id=auth.uid());
CREATE TABLE public.scan_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, business_id uuid NOT NULL REFERENCES public.businesses(id), kind text NOT NULL CHECK(kind IN('view','click','review')), source text NOT NULL DEFAULT 'direct', link_id text, occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.scan_events TO authenticated;
GRANT ALL ON public.scan_events TO service_role;
ALTER TABLE public.scan_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_owner_read ON public.scan_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=business_id AND b.owner_id=auth.uid()));
CREATE INDEX events_business_time ON public.scan_events(business_id,occurred_at);
CREATE POLICY media_public_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='business-media');
CREATE POLICY media_owner_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='business-media' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY media_owner_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='business-media' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='business-media' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY media_owner_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='business-media' AND (storage.foldername(name))[1]=auth.uid()::text);